package main
import("fmt";"log";"q15-employee-capstone-no-rest/database";"q15-employee-capstone-no-rest/model";"q15-employee-capstone-no-rest/repository";"q15-employee-capstone-no-rest/service")
func main(){log.Println("Capstone console version - REST API excluded");db:=database.ConnectDB();defer db.Close();ur:=repository.NewUserRepository(db);er:=repository.NewEmployeeRepository(db);auth:=service.NewAuthService(ur);emp:=service.NewEmployeeService(er);if e:=auth.Register("admin","admin123","ADMIN");e!=nil{log.Println("Register:",e)};u,e:=auth.Login("admin","admin123");if e!=nil{log.Fatal(e)};fmt.Println("Logged in:",u.Username,u.Role);if e=emp.Create(model.Employee{Name:"Demo",Email:"demo@example.com",Salary:50000});e!=nil{log.Println(e)};xs,e:=emp.List(1,5,"");if e!=nil{log.Fatal(e)};fmt.Println("Employees:",xs);if len(xs)>0{fmt.Println("Salary update:",emp.UpdateSalary(xs[0].ID,55000))}}
